<script setup>
import { onMounted,reactive,ref } from 'vue';import { useRouter } from 'vue-router';import http from '../api/http';import { useAuthStore } from '../stores/auth';import { dateText,statusText } from '../utils/format';import { Location,Clock,Search } from '@element-plus/icons-vue'
const records=ref([]),total=ref(0),loading=ref(false),query=reactive({page:1,size:12,keyword:'',category:'',status:'RECRUITING'}),router=useRouter(),auth=useAuthStore();const categories=['校园活动','课程辅导','生活服务','物品代取','创意设计','其他'];async function load(){loading.value=true;try{const data=await http.get('/api/public/tasks',{params:query});records.value=data.records;total.value=data.total}finally{loading.value=false}}function open(id){router.push(`/tasks/${id}`)}onMounted(load)
</script>
<template><div><div class="page-head"><div><h1>任务广场</h1><p>发现身边的小需求，用可靠行动赢得积分与信用</p></div><el-button type="primary" size="large" @click="router.push(auth.loggedIn?'/tasks/new':'/login')">发布微任务</el-button></div><div class="filter-bar surface"><el-input v-model="query.keyword" clearable placeholder="搜索任务、地点或关键词" @keyup.enter="query.page=1;load()"><template #prefix><el-icon><Search/></el-icon></template></el-input><el-select v-model="query.category" clearable placeholder="全部分类" @change="query.page=1;load()"><el-option v-for="c in categories" :key="c" :label="c" :value="c"/></el-select><el-select v-model="query.status" @change="query.page=1;load()"><el-option label="招募中" value="RECRUITING"/><el-option label="已完成" value="COMPLETED"/></el-select><el-button @click="query.page=1;load()">筛选</el-button></div><div v-loading="loading" class="grid"><article v-for="task in records" :key="task.id" class="task-card surface" @click="open(task.id)"><div class="card-top"><el-tag effect="plain" type="success">{{task.category}}</el-tag><span class="status-pill">{{statusText(task.status)}}</span></div><h3>{{task.title}}</h3><div class="meta-row"><el-icon><Location/></el-icon>{{task.location||'地点待沟通'}}</div><div class="meta-row"><el-icon><Clock/></el-icon>{{dateText(task.taskTime)}}</div><div class="card-bottom"><span class="muted">{{task.publisherNickname}} · 信用 {{task.publisherCredit}}</span><span class="points">{{task.rewardPoints}}<small style="font:12px sans-serif"> 积分</small></span></div></article></div><div v-if="!loading&&!records.length" class="surface empty">暂时没有符合条件的任务，换个条件试试</div><div style="display:flex;justify-content:center;margin-top:26px"><el-pagination v-if="total>query.size" v-model:current-page="query.page" :page-size="query.size" :total="total" layout="prev, pager, next" @current-change="load"/></div></div></template>
